import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"Chorus II: Cross-Request Sparsity Reuse for Efficient Image-to-Video Generation","description":"","frontmatter":{"title":"Chorus II: Cross-Request Sparsity Reuse for Efficient Image-to-Video Generation","arxiv":"2606.25040","date":"2026-06-23","authors":"Hao Liu, Chenghuan Huang, Hao Liu, Xing Cai, Chen Li, Ziyang Ma, Jing Lyu, Nong Xiao, Jiangsu Du","categories":"cs.CV","topics":"跨请求缓存, 稀疏注意力, 视频服务系统","outline":[2,2]},"headers":[],"relativePath":"papers/2606.25040.md","filePath":"papers/2606.25040.md","lastUpdated":null}'),e={name:"papers/2606.25040.md"};function l(r,s,m,i,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="chorus-ii-cross-request-sparsity-reuse-for-efficient-image-to-video-generation" tabindex="-1">Chorus II: Cross-Request Sparsity Reuse for Efficient Image-to-Video Generation <a class="header-anchor" href="#chorus-ii-cross-request-sparsity-reuse-for-efficient-image-to-video-generation" aria-label="Permalink to &quot;Chorus II: Cross-Request Sparsity Reuse for Efficient Image-to-Video Generation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2606.25040" target="_blank" rel="noreferrer">2606.25040</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-06-23</td></tr><tr><td><strong>作者</strong></td><td>Hao Liu, Chenghuan Huang, Hao Liu, Xing Cai, Chen Li, Ziyang Ma, Jing Lyu, Nong Xiao, Jiangsu Du</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>不复用相似历史请求的 latent 特征，而只复用它算好的稀疏注意力掩码，把在线 mask 预测开销压到零，在 4 步蒸馏的 Wan2.2-I2V 上拿到 2.16× 端到端加速。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/acceleration-distillation">加速与蒸馏</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>这篇论文的问题设定是<strong>在线服务</strong>而不是单条生成：一个真实的图生视频服务里，请求高度重复——同一套特效模板、相似的主体、反复出现的镜头布局。已有的加速手段几乎全部只挖掘<strong>单条请求内部</strong>的冗余，要么是相邻去噪步之间的特征相似（TaylorSeer 一类），要么是同一条轨迹上稀疏掩码的可复用性（SVG2 一类）。</p><p>问题在于，步数蒸馏已经成为线上主流：从 50 步压到 4 步之后，<strong>步间冗余本身就变稀薄了</strong>，而所有需要在线摊薄的开销都失去了摊薄的机会。作者用一个具体数字点出这个矛盾：在少步场景下，SVG2 的 mask 预测占整条注意力路径时间的 30% 以上。于是加速方法在最需要它的部署场景里反而最失效。跨请求这个维度就是在这种压力下被逼出来的——它是少步蒸馏之后<strong>唯一还没被开采的冗余来源</strong>。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>跨请求缓存</strong>已有先例：NIRVANA 与 Chorus 证明相似请求之间可以复用 latent 特征。但作者指出一个具体的失败模式并用 PCA 轨迹图展示（图 2）：直接复用 latent 会引入<strong>源请求的内容偏置</strong>，即使特征在分布上看起来很接近，生成轨迹也会偏离「不复用」的基线，表现为身份泄漏、纹理污染、区域错位。在一般场景可以忍，在要求与基线最小偏差的高保真应用里不行。</p><p><strong>稀疏注意力</strong>这条线的分歧在于掩码怎么来：在线预测保留输入自适应但有获取开销，静态模板或离线校准去掉开销但丢失请求级自适应。作者做了一个很有说服力的数学说明来解释为什么廉价预测器必然不准——Sparge-Attn 用均值池化后再算 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0435em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">⊤</span></span></span></span></span></span></span></span></span></span></span>，而 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0991em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">mean</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathrm">softmax</span></span><span class="mopen">(</span><span class="mord mathnormal">Q</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">⊤</span></span></span></span></span></span></span></span><span class="mclose">))</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel"><span class="mrel"><span class="mord vbox"><span class="thinbox"><span class="rlap"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="inner"><span class="mord"><span class="mrel"></span></span></span><span class="fix"></span></span></span></span></span><span class="mspace nobreak"></span><span class="mrel">=</span></span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0991em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">softmax</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathrm">mean</span></span><span class="mopen">(</span><span class="mord mathnormal">Q</span><span class="mclose">)</span><span class="mord"><span class="mord mathrm">mean</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">⊤</span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，softmax 与均值池化不可交换，所以块对得分只能粗略近似真实注意力，退化是<strong>内在的</strong>而非实现问题。</p><p><strong>特征缓存</strong>（DeepCache、ToCa、TeaCache、TaylorSeer）依赖强步间冗余，少步采样下相邻状态距离拉大，效果自然下滑。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>线上服务团队最先看到的一定是流量画像：请求分布高度集中，同一套模板被反复调用。第一个念头必然是复用特征——这就是 Chorus 一代做的事。做完之后遇到的真实反馈是画面被污染，于是问题变成：<strong>在「相似请求之间」还有什么东西可以安全地共享？</strong></p><p>关键的观念转折是把复用对象从「内容」换成「计算的路由」。稀疏掩码本身不携带源请求的像素信息，它只决定当前请求的哪些块之间允许交互；即使掩码略有偏差，输出仍然完全由当前请求的 Q/K/V 决定。这是一个「结构性复用」而非「内容性复用」的目标。</p><p>接下来必须验证掩码到底可不可复用。作者定义了一个比 IoU 更贴近下游影响的度量——<strong>覆盖率</strong>：从相似请求取来的掩码所选块，覆盖了目标请求真实注意力质量的多少。测得的结果是：在约 30% 的保留率下，跨请求掩码覆盖 85.12%，只比同请求 oracle 的 90.09% 低 4.97 个百分点，却比 Sparge-Attn 的 80.80% 高 4.32 个百分点。而且覆盖率随两条请求的条件相似度单调上升。这一步一旦成立，剩下的就是系统工程：向量库检索、相似度阈值、失配时的兜底、以及把已知的稀疏度分布用于多卡负载均衡。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>块级稀疏注意力的形状主要由<strong>全局场景结构</strong>决定，而不是高频细节；语义相似的两条 I2V 请求共享全局结构，因此共享稀疏拓扑。既然历史请求在自己生成时<strong>本来就要算一遍注意力</strong>，那么它的高质量掩码是免费的副产品——把它存下来给新请求用，就等于把「精确掩码构造」的成本在整个请求流上摊薄到接近零，同时又不像特征复用那样把源请求的内容带进来。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以「用户上传一张猫的照片，套用一个已被大量调用的运镜模板」为例。</p><ol><li><strong>检索</strong>：把文本 prompt 与条件图编码成 embedding 存入向量库（ChromaDB 一类），新请求做联合 embedding 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span>-NN 余弦检索；若与最近邻的相似度超过阈值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span>（部署中图像条件 DINO 相似度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.4</span></span></span></span>），加载其缓存掩码，否则回落到在线稀疏预测或稠密注意力。</li><li><strong>掩码来源</strong>：历史请求若走稠密路径，就从其注意力图按 top-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span> 加 top-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 下限选块；若本身走高精度稀疏路径，块级掩码已经现成。掩码按去噪步、层、head 三级索引存储。</li><li><strong>安全兜底（两级）</strong>：(a) <em>块对访问刷新</em>——维护二值访问图 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mopen">[</span><span class="mord mathnormal">h</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mclose">]</span></span></span></span>，以连续 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span> 层为一组，组内逐层更新，执行到组末层时把仍未被访问过的块对强制并入掩码，保证每个 Q/K 块对在每组内至少被触达一次；(b) <em>最小 top-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 保底</em>——某些 head 的注意力极度尖峰，纯 top-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span> 只留下少数几个块对，跨请求的轻微漂移就足以让它们错位，因此缓存时强制每个 head 至少保留 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.0315em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mop mtight"><span class="mtight">m</span><span class="mtight">i</span><span class="mtight">n</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 比例的 key 块。</li><li><strong>头级调度</strong>：由于 top-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span> + top-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 下限给每个 head 分配了不同稀疏度，Ulysses 序列并行下各 GPU 负载不均。稀疏复用的一个额外好处是<strong>稀疏度分布提前已知</strong>，可以在 all-to-all 之前贪心重排 head，把重负载 head 分给当前最轻的 GPU，实测 8 卡下端到端再快约 7.28%。</li><li><strong>可选的激进路径</strong>：下采样 latent 特征复用。原始 Chorus 式区域隔离复用会在边界产生模糊与撕裂；缓存非计算区所有层的 KV 又太贵（作者估计在 Wan2.2 上比缓存原始 latent 多约 160× 存储）。折中做法是对非计算区做时空下采样池化，把降采样后的序列与活跃序列拼接送入注意力，让活跃 token 保有近乎完整的全局感受野。</li><li><strong>引导增强</strong>：复用会削弱图像条件。两个训练无关的补偿——首帧 key 放大 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mopen">[</span><span class="mrel">:</span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">:</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">]</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">←</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0528em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">step</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mopen">[</span><span class="mrel">:</span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">:</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">]</span></span></span></span>（只改 K，不动 Q/V，抬高首帧列在 softmax 中的竞争力）；patch embedding 阶段把条件分支放大，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">e</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">Conv3d</span></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">x</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0037em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">step</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathrm">Conv3d</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span></span></span></span>。二者只在复用开始后启用并随步数衰减。</li></ol><p>实验设置：Wan2.2-I2V（MoE），lightx2v LoRA 把采样步从 50 压到 4，720p、61 帧、每帧 3600 token，DPM-Solver++，NVIDIA H20。条件图取自 COCO 2017，prompt 来自真实线上业务。sparsity reuse 固定 layer_flash=8、Q_block=64、K_block=128，默认配置 top_p=0.95 / min_top_k=0.1，turbo 配置 top_p=0.9 / min_top_k=0.0。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化不多，核心只有两处，但都值得讲清楚。</p><p><strong>廉价掩码预测为何必然有偏</strong>。Sparge-Attn 类方法用块均值近似块对得分，而</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2491em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathrm">mean</span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathrm">softmax</span></span><span class="mopen">(</span><span class="mord mathnormal">Q</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">⊤</span></span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mspace"> </span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel"><span class="mrel"><span class="mord vbox"><span class="thinbox"><span class="rlap"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="inner"><span class="mord"><span class="mrel"></span></span></span><span class="fix"></span></span></span></span></span><span class="mspace nobreak"></span><span class="mrel">=</span></span><span class="mspace"> </span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2491em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathrm">softmax</span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathrm">mean</span></span><span class="mopen">(</span><span class="mord mathnormal">Q</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm">mean</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">⊤</span></span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mord">.</span></span></span></span></span></p><p>softmax 是凸函数意义上的非线性变换，由 Jensen 不等式，先池化再指数化会系统性低估块内少数高分项的贡献。因此块对得分对真实注意力质量的排序是有偏的，top-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span> 掩码质量的下降不能靠工程优化消除——这解释了表 2 中 Sparge-Attn 的 GT 覆盖率停在 86.6%。</p><p><strong>路由开销比</strong>。作者定义</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">Routing Overhead Ratio</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.2408em;vertical-align:-0.8804em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">Attention Latency</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">Routing Time</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8804em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mpunct">,</span></span></span></span></span></p><p>比值越低越接近稠密注意力的零开销行为。表 2 显示 SVG2 三档配置的比值为 31%–55%，也就是说它把三到五成的注意力时间花在「决定算什么」而不是「算」上。这个指标是本文最有价值的分析工具：它把稀疏方法的评估从「密度对画质」的二维平面，扩展到把 mask 获取成本显式计入的三维空间。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：跨请求掩码复用能否同时拿到高覆盖与零开销？</strong> 表 2 把注意力路径单独剖开。FlashAttention 基线 751 ms；SVG2 默认档路由 339 ms、开销比 54.7%、密度 29.1%、覆盖 90.1%、总延迟 620 ms；本方法 fp16 默认档路由 0 ms、密度 39.5%、覆盖 92.0%、总延迟 321 ms（2.34×）。fp8 档下 Sparge-Attn 密度 40.0%、覆盖 86.6%、121 ms；本方法密度 35.2%、覆盖 88.1%、112 ms（6.71×）。</p><p>需要指出一个口径问题：<strong>fp16 档的覆盖率比较不是等密度的</strong>——本方法密度 39.5% 明显高于 SVG2 的 29.1%，更高的密度自然带来更高的覆盖率，因此「覆盖率超过 SVG2」这一条并不构成掩码更准的证据。相反 fp8 档是干净的（35.2% 密度对 40.0%，覆盖反而更高），这一档的结论成立。</p><p><strong>问题二：端到端质量与速度？</strong> 表 1 以 4 步蒸馏 + 稠密 FlashAttention 为基线（170.1 s）。本方法默认稀疏复用 78.9 s（2.16×），PSNR 23.252 / SSIM 0.818 / LPIPS 0.120 / CLIP-F 0.9859，与 SVG2 默认档（23.124 / 0.817 / 0.118 / 0.9866，160.0 s）基本持平而延迟减半。VBench-Q 各方法在 0.786–0.790 之间，只有 Sparge-Attn 极稀疏档（top-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span>=0.08）掉到 0.779、DINO-I 掉到 0.894。</p><p>这里有一个论文没有正面讨论、但对读者判断价值极其关键的数字：<strong>SageAttention（纯稠密 FP8 量化，无任何稀疏）只用 91.8 s（1.85×），PSNR 24.817——比包括本方法在内的所有稀疏方案都高</strong>。也就是说，2.16× 里的绝大部分来自 FP8 量化后端；稀疏复用相对稠密 FP8 的边际收益是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">91.8/78.9</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1.16</span><span class="mord">×</span></span></span></span>，而代价是约 1.57 dB 的 PSNR。同样，fp16 下本方法的 129.8 s（1.31×）与静态 Radial-Attn 的 130.0 s（1.31×）<strong>端到端加速比完全相同</strong>，本方法赢的是保真度（23.273 vs 20.043）而不是速度。</p><p><strong>问题三：复用的可靠性取决于什么？</strong> 图 7 给出 GT 覆盖率随 DINO 相似度的单调上升曲线，作者据此确定阈值：相似度超过 0.3 时，检索掩码的覆盖率已高于 Sparge-Attn 的在线预测。</p><p><strong>问题四：可选的特征复用路径值不值？</strong> 表 3 在纯特征复用路径（不含稀疏复用）上做消融，基线是 SageAttention 91.8 s。下采样把 VBench-Q 从 0.775/0.777 抬到 0.788；引导增强把 DINO-I 从 0.917 抬到 0.922、CLIP-T 从 24.01 抬到 24.32；四种配置的延迟都在 78.5–79.5 s（1.15–1.17×）。</p><p>但表 1 里合并了稀疏与特征复用的配置暴露出这条路径的真实性质：PSNR 13.211 / SSIM 0.500 / LPIPS 0.461，与稠密基线的偏差巨大，<strong>却拿到全表最高的 DINO-I 0.924 与 CLIP-T 24.50（均高于稠密基线的 0.922 / 24.12）</strong>。一个加速方法在条件贴合度上超过它要逼近的基线，最自然的解释是引导增强把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span> 放大后改变了采样分布，等价于换了一个「条件更强」的采样器，而不是更忠实的近似。作者把它定位成「speed-first 操作点」，措辞是克制的，但这条路径不应被读作加速。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：少步蒸馏抽干了单请求内部的冗余，跨请求冗余成为唯一未开采的维度。复用相似请求的 latent 会带来内容偏置，复用它们的<strong>稀疏掩码</strong>则只共享计算路由、不共享像素，是更安全的复用目标。实测在 30% 保留率下跨请求掩码覆盖目标真实注意力质量的 85.12%，仅比同请求 oracle 低 4.97 个百分点。系统侧配上向量检索、两级安全兜底（块对访问刷新 + 最小 top-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span>）与提前已知稀疏度带来的 head 负载均衡（8 卡再快 7.28%），把路由开销比从 SVG2 的 31%–55% 压到 0%。端到端在 Wan2.2-I2V 4 步设定下 2.16×，与 SVG2 保真度相当而延迟减半——但相对纯稠密 FP8 的 SageAttention 只快 1.16× 且 PSNR 低约 1.6 dB。</p><p><strong>三句话版</strong>：把「在线搜掩码」换成「检索历史掩码」，是少步蒸馏时代唯一能同时保住掩码质量与零开销的路径。真实收益需要与稠密 FP8 量化对齐后再读：稀疏本身贡献的是 1.16×，其余来自量化后端。全部结论建立在暖缓存假设上，命中率本身从未被测量。</p><p><strong>一句话版</strong>：稀疏注意力的掩码是可以跨请求共享的公共品，因为它编码的是场景结构而不是内容。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条不是掩码可不可复用，而是<strong>缓存命中率足够高</strong>。论文在实验设置里写得很直白：「为了测量稀疏复用本身的算法效果，所有复用变体都在<strong>暖缓存</strong>下评测；部署时图像条件相似度低于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.4</span></span></span></span> 的请求回落到在线稀疏注意力」。也就是说，表 1 中的 2.16× 是<strong>命中条件下的上界</strong>，真实服务的期望加速是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7778em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord">hit</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2.16</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">hit</span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord text"><span class="mord cjk_fallback">回落方案的加速</span></span><span class="mclose">)</span></span></span></span>，而 hit 从未被测量。</p><p>这不是一个可以靠工程弥补的细节：整篇论文的价值命题就是「真实 I2V 流量高度重复」，而支撑这一命题的全部证据是引言里的定性描述（特效模板、相似主体、重复镜头布局）和一条 COCO 图像 + 线上 prompt 的构造集。作者在 Limitations 里承认「一般化工作负载可能需要更大规模的检索库来保证命中率」，但没有给出任何真实流量的相似度分布直方图，也没有给出冷启动曲线（缓存从空到稳态需要多少请求）。更进一步，掩码按「去噪步 × 层 × head」三级索引存储——以 Wan2.2-I2V 的规模，单条请求的掩码集合本身就是可观的存储量，而论文完全没有报告缓存条目的大小、淘汰策略与内存预算。</p><p>一条真实流量的相似度分布，比表 1 里任何一行数字都更能决定这套方法能不能用。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要 GPU 集群，也不需要实现 kernel：</p><ul><li><strong>数据</strong>：任意公开的 I2V 请求代理集（例如从公开视频数据集抽首帧 + 其字幕作为 prompt），构造两种流量：<em>模板型</em>（少量主体 + 大量重复运镜描述）与<em>长尾型</em>（主体与描述都高度多样）。</li><li><strong>实现</strong>：只实现检索侧。用 CLIP/DINO 编码图文条件建向量库，模拟请求流按时间顺序到达，记录每条请求与库中最近邻的相似度。</li><li><strong>测量</strong>：(a) 在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.4</span></span></span></span> 下的命中率随请求数的变化曲线（冷启动到稳态）；(b) 命中请求占总计算量的比例；(c) 按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7778em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord">hit</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2.16</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">hit</span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.31</span></span></span></span> 估算的期望端到端加速。</li><li><strong>判据</strong>：若长尾型流量的稳态命中率低于 40%，期望加速会跌到 1.6× 以下，即低于纯稠密 FP8 的 1.85×——此时整套稀疏复用在该流量上没有收益。若模板型流量命中率 &gt;80%，则该方法的适用边界被清晰界定为「模板化业务」，这本身就是有价值的结论。</li></ul><p>这个实验一周内可完成，且是全文最需要而恰恰缺失的那一组数据。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是构造一个场景，让<strong>掩码复用可预测地失败而检索相似度却很高</strong>。</p><p>思路：稀疏拓扑由全局场景结构决定这一前提，反过来意味着<strong>两条全局结构相同但局部运动完全不同的请求会被判为相似</strong>。取同一张条件图（例如一间静止的房间），配两条 prompt：一条是「镜头缓慢平移」，一条是「画面中央的人突然跑向左侧」。二者的图像条件 DINO 相似度为 1.0（同一张图），文本 embedding 也不会差太远，必然命中同一条缓存。但注意力的时间维依赖结构截然不同——大位移场景需要跨帧的长程块对，静止场景不需要。此时复用掩码会系统性地裁掉运动相关的块对，可预期的表现是运动被抑制、动态度下降。</p><p>这个反例的杀伤力在于它同时给出<strong>替代解释</strong>：本文报告的高保真度（PSNR 23.25、CLIP-F 0.986）可能部分来自「复用掩码倾向于保留静态结构、抑制大位移」这一保守化偏置——而 PSNR/SSIM/LPIPS 恰恰奖励保守。论文的 VBench-Q 是六个子维度的<strong>平均值</strong>（含 Dynamic Degree），平均会把单项下降稀释掉；全文没有单独报告 Dynamic Degree。补上按运动幅度分层的评测（把测试集按光流幅度分成高/中/低三档分别报告 VBench 子项），就能判定这是保守化还是真加速。</p><p>第二条攻击针对引导增强：把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9805em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0037em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">step</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0528em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">step</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 加到<strong>不复用的稠密基线</strong>上，看 DINO-I 与 CLIP-T 是否同样上升。若上升，则表 1 中特征复用路径的条件贴合度优势与复用无关，纯粹是条件放大的效果。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>把跨请求复用从「检索最相似的一条」改写成「在请求流上摊薄一个共享的稀疏基底」。</strong></p><p>驱动它的局限有两条：一是命中率决定一切，而 1-NN 检索在长尾流量上必然失效；二是掩码按步/层/head 三级存储，条目粒度与请求一一对应，存储随请求数线性增长。这两个问题的根源是同一个——<strong>把掩码当成请求的私有资产</strong>。</p><p>可借鉴的相邻领域工具是推荐系统与压缩感知里的<strong>字典学习</strong>：不为每条历史请求存一张掩码，而是在请求流上在线学习一组稀疏基底（若干张原型掩码），新请求只需要预测一个极低维的组合系数（甚至只是 top-1 原型的 id）。这与同期论文中 ScalingAttention 的「权重编码拓扑」形成直接对话：后者主张存在一个 prompt 无关的全局包络，本文主张存在请求条件化的局部拓扑；字典学习恰好是这两个极端之间的连续谱——原型数为 1 时退化为静态拓扑，原型数等于请求数时退化为本文方案。</p><p>第一个实验：收集若干千条请求的高质量掩码，对每个 (层, head) 位置的掩码集合做聚类，测量「用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> 个原型覆盖全部请求」时 GT 覆盖率随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> 的曲线。若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">16</span></span></span></span> 就能达到本文 1-NN 检索 92% 的覆盖水平，那么存储从 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mopen">(</span><span class="mord text"><span class="mord cjk_fallback">请求数</span></span><span class="mclose">)</span></span></span></span> 降到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mopen">(</span><span class="mord">1</span><span class="mclose">)</span></span></span></span>，冷启动问题消失，长尾流量也能受益——这将把跨请求复用从「模板化业务的优化」变成「通用服务的默认配置」。</p>',58)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
